        self.stack = []
        self.mins = []

    def push(self, value) -> None:
        self.stack.append(value)
        self.mins.append(value if not self.mins else min(value, self.mins[-1]))

    def pop(self):
        if not self.stack:
            return None
        self.mins.pop()
        return self.stack.pop()

    def top(self):
        return self.stack[-1] if self.stack else None

    def get_min(self):
